# Code generated by Claude
"""
How much the wall-segment count slows the physics (David, Oct 26, step 3). Physics only: the robot settled at the spawn pose with the beaker resting on the hotplate (its own contact pairs against both
fingers and the palm are present), ctrl held, mj_step only (no control loop, no rendering). CPU time per simulated second (time.process_time, so another process's load does not count), the segment
counts alternated and repeated, the first repeat of each discarded. Reports the median of the rest and the number of geoms and contact pairs.

    MUJOCO_GL=egl python experiments/beaker_segments_timing.py [--segments 24 48] [--repeats 5] [--sim-s 3.0]
"""
import argparse, gc, json, os, statistics, sys, time
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
os.environ.setdefault("MUJOCO_GL", "egl")
import mujoco  # noqa: E402

from src.task_beaker_hotplate import load_task, spawn_and_settle  # noqa: E402
from src.task_config import BEAKER_CFG, TASK_CFG  # noqa: E402


def run_once(n, sim_s):
    sim = load_task(TASK_CFG, cameras=False, beaker_cfg={**BEAKER_CFG, "n_segments": n})
    st = spawn_and_settle(sim)
    m, d = sim.model, sim.data
    steps = int(round(sim_s / m.opt.timestep))
    t0 = time.process_time()
    for _ in range(steps):
        d.ctrl[:] = st["hold"]
        st["ff"].apply(d.ctrl, d)
        mujoco.mj_step(m, d)
    cpu = time.process_time() - t0
    info = {"ngeom": int(m.ngeom), "npair": int(m.npair), "ncon_end": int(d.ncon), "timestep": float(m.opt.timestep)}
    del sim
    gc.collect()
    return cpu / (steps * m.opt.timestep), info


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--segments", type=int, nargs="+", default=[24, 48])
    ap.add_argument("--repeats", type=int, default=5)
    ap.add_argument("--sim-s", type=float, default=3.0)
    ap.add_argument("--out", default=None)
    a = ap.parse_args()
    res = {n: [] for n in a.segments}
    info = {}
    for r in range(a.repeats):
        for n in a.segments:
            v, info[n] = run_once(n, a.sim_s)
            res[n].append(v)
            print(f"repeat {r} segments {n}: {v:.3f} cpu-s per simulated s  {info[n]}", flush=True)
    out = {}
    for n in a.segments:
        kept = res[n][1:] if len(res[n]) > 1 else res[n]
        out[n] = {"median_cpu_s_per_sim_s": statistics.median(kept), "all": res[n], **info[n]}
        print(f"segments {n}: median {out[n]['median_cpu_s_per_sim_s']:.3f} cpu-s per simulated s (kept {len(kept)} of {len(res[n])}); geoms {info[n]['ngeom']}, pairs {info[n]['npair']}", flush=True)
    if len(a.segments) == 2:
        x, y = (out[n]["median_cpu_s_per_sim_s"] for n in a.segments)
        print(f"ratio {a.segments[1]} / {a.segments[0]}: {y / x:.3f}")
    if a.out:
        Path(a.out).parent.mkdir(parents=True, exist_ok=True)
        Path(a.out).write_text(json.dumps(out, indent=1))


if __name__ == "__main__":
    main()
